  public void Present(){if(!Ready||owner==null)return;bool enabled=current.Enabled&&current.Focused&&!current.Paused&&owner.Equipped&&!owner.Retired;View.Present(owner,first,second,neutral[dominant],neutral[1-dominant],current.Hand(dominant).Tracked,current.Hand(1-dominant).Tracked,enabled);}
